  on:"on",off:"off",logT:"The log, February",stopped:"stopped",exposed:"exposed",lapS:"Laptop",keyS:"Key",
  logIdle:["Press the regulator's question to read it."],logNo:["data_loader · read bank_details","data_loader · read bank_details","data_loader · read bank_details · 4,812 times"],
  logId:["billing_load · read bank_details","Lena Park · read bank_details","outage_dash · read bank_details"],logLeast:["billing_load · read bank_details","refunds_job · read bank_details","billing team · 3 people, by name"],
